#include <bits/stdc++.h>
using namespace std;

int main(){
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, m;
    cin >> n >> m;

    int a[10];
    for(int i=0;i<10;i++) cin >> a[i];

    vector<vector<int>> adj(n+1), radj(n+1);
    vector<unordered_set<int>> aset(n+1);

    for(int i=0;i<m;i++){
        int u,v; cin >> u >> v;
        adj[u].push_back(v);
        radj[v].push_back(u);
        aset[u].insert(v);
    }

    auto now = chrono::steady_clock::now;
    auto start_time = now();

    mt19937 rng(12345);

    vector<int> best_path;

    while(chrono::duration_cast<chrono::milliseconds>(now()-start_time).count() < 4000){
        int sv = rng()%n + 1;

        vector<int> path;
        vector<bool> used(n+1, false);
        path.push_back(sv);
        used[sv] = true;

        // Build path greedily with Warnsdorff + randomness
        auto extend_back = [&]() -> bool {
            int cur = path.back();
            int best = -1, best_score = INT_MAX;
            for(int v : adj[cur]){
                if(!used[v]){
                    int sc = 0;
                    for(int w : adj[v]) if(!used[w]) sc++;
                    if(sc < best_score || (sc == best_score && (rng()%3==0))){
                        best_score = sc; best = v;
                    }
                }
            }
            if(best == -1) return false;
            path.push_back(best);
            used[best] = true;
            return true;
        };

        while(extend_back());

        // Rotation-extension: when stuck at back, find i such that path[back]->path[i+1] exists
        // and path[i]->some unused vertex exists. Then reverse path[i+1..back], try extending again.
        for(int attempts = 0; attempts < 2000 && (int)path.size() < n; attempts++){
            int tail = path.back();
            // Collect positions where tail has edge to path[i] for i in [1..sz-2]
            // Then we can reverse suffix from i to end
            vector<int> cands;
            int sz = (int)path.size();
            // path[i] is target of tail, meaning aset[tail].count(path[i])
            // Then new path = path[0..i-1] + reversed(path[i..sz-1])
            // New tail = path[i], but we need path[i-1]->path[sz-1] edge? No:
            // Actually: new path = path[0..i] + reverse(path[i+1..sz-1])
            // requires edge tail -> path[i+1]... Let me think again.
            // We need: aset[tail] contains path[j] for some j, 0<=j<=sz-2
            // new path: path[0..j], then reverse(path[j+1..sz-1])
            // needs edge path[j]->path[sz-1] — no, path[j]->tail is already there since tail->path[j]? No, directed.
            // We need edge from tail to path[j]. Then new_path = path[0..j-1] + reverse(path[j..sz-1]).
            // New tail is path[j]. But we need edge path[j-1]->path[sz-1] (the old tail becomes position j).
            // Actually simpler: if aset[tail].count(path[j]) for j<sz-1, reverse path[j+1..end]. New tail = path[j+1].
            for(int j=0;j<sz-2;j++){
                if(aset[tail].count(path[j])){
                    cands.push_back(j);
                }
            }
            if(cands.empty()) break;
            int j = cands[rng()%cands.size()];
            reverse(path.begin()+j+1, path.end());
            while(extend_back());
        }

        if((int)path.size() > (int)best_path.size()) best_path = path;
        if((int)best_path.size() == n) break;
    }

    cout << best_path.size() << "\n";
    for(int i=0;i<(int)best_path.size();i++){
        cout << best_path[i];
        if(i+1<(int)best_path.size()) cout << ' ';
    }
    cout << "\n";
}
